class Solution {
  public int minMoves(String[] classroom, int energy) {
    int m = classroom.length, n = classroom[0].length();
    int[][] litterId = new int[m][n];
    int litters = 0, start = 0;
    for (int i = 0; i < m; i++) {
      for (int j = 0; j < n; j++) {
        litterId[i][j] = -1;
        char c = classroom[i].charAt(j);
        if (c == 'L') litterId[i][j] = litters++;
        else if (c == 'S') start = i * n + j;
      }
    }
    if (litters == 0) return 0;
    int masks = 1 << litters, full = masks - 1, levels = energy + 1;
    boolean[] visited = new boolean[m * n * masks * levels];
    int[] dr = {1, -1, 0, 0}, dc = {0, 0, 1, -1};
    int[] cur = new int[1024], next = new int[1024];
    int curSize = 0, nextSize;
    int first = (start * masks) * levels + energy;
    visited[first] = true;
    cur[curSize++] = first;
    for (int moves = 1; curSize > 0; moves++) {
      nextSize = 0;
      for (int s = 0; s < curSize; s++) {
        int state = cur[s];
        int e = state % levels, rest = state / levels;
        int mask = rest % masks, cell = rest / masks;
        if (e == 0) continue;
        int r = cell / n, c = cell % n;
        for (int d = 0; d < 4; d++) {
          int nr = r + dr[d], nc = c + dc[d];
          if (nr < 0 || nc < 0 || nr >= m || nc >= n) continue;
          char ch = classroom[nr].charAt(nc);
          if (ch == 'X') continue;
          int ne = ch == 'R' ? energy : e - 1;
          int nmask = litterId[nr][nc] >= 0 ? mask | (1 << litterId[nr][nc]) : mask;
          if (nmask == full) return moves;
          int ns = (((nr * n + nc) * masks) + nmask) * levels + ne;
          if (visited[ns]) continue;
          visited[ns] = true;
          if (nextSize == next.length) next = Arrays.copyOf(next, nextSize * 2);
          next[nextSize++] = ns;
        }
      }
      int[] t = cur;
      cur = next;
      next = t;
      curSize = nextSize;
    }
    return -1;
  }
}
